import{J as e,n as t,ot as n,q as r}from"./chunks/framework.8ZHN87l8.js";var i=JSON.parse(`{"title":"The eight packets protocol 2225 added","description":"","frontmatter":{"title":"The eight packets protocol 2225 added","group":"Documents","category":"Research","head":[["meta",{"property":"og:title","content":"The eight packets protocol 2225 added"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/research/protocol-2225-added-packets"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/research/protocol-2225-added-packets"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/research/protocol-2225-added-packets.md"}},"headers":[],"relativePath":"research/protocol-2225-added-packets.md","filePath":"research/protocol-2225-added-packets.md","lastUpdated":1793391970000}`),a={name:`research/protocol-2225-added-packets.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="the-eight-packets-protocol-2225-added" tabindex="-1">The eight packets protocol 2225 added <a class="header-anchor" href="#the-eight-packets-protocol-2225-added" aria-label="Permalink to “The eight packets protocol 2225 added”">​</a></h1><p>Protocol 2225 (Minecraft 1.26.60) added eight packets and renumbered nothing. Their ids have been in <code>packages/protocol/src/wire/versions/v2225.ts</code> since the delta codec landed, as protocol surface a codec knows about; this note records the field layout of each so they can be implemented rather than decoded to <code>null</code>.</p><h2 id="where-these-layouts-come-from" tabindex="-1">Where these layouts come from <a class="header-anchor" href="#where-these-layouts-come-from" aria-label="Permalink to “Where these layouts come from”">​</a></h2><p>Mojang&#39;s <code>bedrock-protocol-docs</code> release <strong>v1.26.60</strong>, the <code>metadata.zip</code> this repository already pins in <code>packages/minecraft/datagen/manifest.json</code> (sha256 <code>a030a45d825b9ec8ea6bb744283648d5db1c0111592a8fd5eb0096ff05a0464b</code>). Every schema in it declares <code>&quot;x-protocol-version&quot;: 2225</code>. Field order is each property&#39;s <code>x-ordinal-index</code>; the wire type is <code>x-underlying-type</code> plus <code>x-serialization-options</code>.</p><p>Two conventions decide the cases a reader would otherwise have to guess at, and both are read off the schema rather than assumed:</p><ul><li><strong><code>Compression</code> means a varint.</strong> An <code>int32</code> or <code>int64</code> carrying <code>&quot;x-serialization-options&quot;: [&quot;Compression&quot;]</code> travels ZigZag-varint encoded, not fixed-width. <code>ActorUniqueID</code> is an <code>int64</code> with <code>Compression</code>, which matches how <code>StartGamePacket</code> already writes <code>entityId</code> as <code>t.varint64</code>. <code>Recipe Index</code> is an <code>int32</code> with <code>Compression</code>, so it is a ZigZag varint32 and <strong>not</strong> a little-endian <code>li32</code>.</li><li><strong>A property absent from <code>required</code> is optional on the wire</strong>: a presence <code>bool</code>, then the value when set. This is the shape <code>PassengerOfBlockArguments</code> already travels in where <code>AddActorPacket</code> carries it.</li></ul><p>Unverified against a second implementation: gophertunnel v1.63.0 predates 1.26.60 and carries none of these packets, and no capture exercises them (a vanilla login sends none, so they are absent from the wire fixtures). The schemas are the sole source, which is why each definition below records its ordinals. The first capture that contains one of these packets will check it through the <code>protocol.wire-roundtrip</code> parity family like any other.</p><h2 id="shared-structures" tabindex="-1">Shared structures <a class="header-anchor" href="#shared-structures" aria-label="Permalink to “Shared structures”">​</a></h2><table tabindex="0"><thead><tr><th>Structure</th><th>Layout</th></tr></thead><tbody><tr><td><code>ActorUniqueID</code></td><td><code>int64</code> + Compression → ZigZag varint64</td></tr><tr><td><code>SignedAudioContent</code></td><td><code>Compact JWT</code>: one <code>string</code></td></tr><tr><td><code>MatchmakingStateOptions</code></td><td><code>Triggering Player Name</code> string, <code>Triggered By Local Player</code> bool</td></tr><tr><td><code>PassengerOfBlockArguments</code></td><td><code>BlockPos</code>, <code>Offset</code> Vec3, <code>Rotation</code> float, <code>RotationLimit</code> float, <code>EmoteType</code> uint8</td></tr><tr><td><code>ServerSoundHandle</code></td><td>one <code>uint64</code></td></tr><tr><td><code>AudioContentRegistrationEntry</code></td><td><code>Audio Content ID</code> string, then <code>Shared Metadata</code>, <code>Server Content</code>, <code>Playback Content</code>, each a <code>SignedAudioContent</code></td></tr><tr><td><code>PlaySoundPacketPayload</code></td><td><code>Name</code> string, <code>Position</code> BlockPos, <code>Volume</code> float, <code>Pitch</code> float, <code>Loop Count</code> int32+Compression, <code>Bypass Listener Range Check</code> bool, <code>Server Sound Handle</code> (optional), <code>Playback Position Seconds</code> float (optional)</td></tr></tbody></table><p>Enums, with their <code>x-enum-binary-value</code> numbering:</p><ul><li><code>MatchmakingState</code> (uint8): Idle 0, Matchmaking 1, MatchFound 2, Canceled 3, PlayerLeftParty 4, PlayerLeftServer 5, ServerShutdown 6, TimedOut 7, RequeueAsParty 8.</li><li><code>CursorItemDragState</code> (uint8): Start 0, Stop 1.</li><li><code>AudioContentPlaybackType</code> (uint8): Music 0, Sound 1.</li><li><code>PassengerOfBlockArguments::EmoteType</code> (uint8): Standing 0, Riding 1, Laying 2.</li></ul><h2 id="the-packets" tabindex="-1">The packets <a class="header-anchor" href="#the-packets" aria-label="Permalink to “The packets”">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Packet</th><th>Fields, in ordinal order</th></tr></thead><tbody><tr><td>0x161</td><td><code>ClientboundMatchmakingStatePacket</code></td><td><code>State</code> uint8; <code>Destination Name</code> string; <code>Options</code> optional <code>MatchmakingStateOptions</code></td></tr><tr><td>0x162</td><td><code>ServerboundStonecutterSetRecipePacket</code></td><td><code>Container Id</code> uint8; <code>Recipe Index</code> varint32</td></tr><tr><td>0x163</td><td><code>ClientboundStonecutterSetRecipePacket</code></td><td><code>Player Id</code> varint64; <code>Container Id</code> uint8; <code>Recipe Index</code> varint32</td></tr><tr><td>0x164</td><td><code>ServerboundMatchmakingCancelPacket</code></td><td>none; the payload schema declares no properties</td></tr><tr><td>0x165</td><td><code>SetPassengerOfBlockPacket</code></td><td><code>Passenger</code> varint64; <code>PassengerOfBlockData</code> optional <code>PassengerOfBlockArguments</code></td></tr><tr><td>0x166</td><td><code>ServerboundCursorItemDragPacket</code></td><td><code>State</code> uint8</td></tr><tr><td>0x167</td><td><code>ClientboundPlayAudioContentPacket</code></td><td><code>Shared Metadata</code> SignedAudioContent; <code>Playback Content</code> SignedAudioContent; <code>Playback Type</code> uint8; <code>Play Sound</code> PlaySoundPacketPayload</td></tr><tr><td>0x168</td><td><code>ServerboundRegisterAudioContentPacket</code></td><td><code>Registrations</code> list of <code>AudioContentRegistrationEntry</code></td></tr></tbody></table><p>Note that <code>ClientboundMatchmakingStatePacket</code> lists <code>State</code> at ordinal 0 and <code>Destination Name</code> at ordinal 1, so the enum travels first despite reading second in the schema&#39;s alphabetical property order. Ordinals, not property order, decide the wire.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};